create extension if not exists pgcrypto;

create table if not exists public.questions (
  id uuid primary key default gen_random_uuid(),
  question_text text not null,
  option_a text not null,
  option_b text not null,
  option_c text not null,
  option_d text not null,
  correct_option text not null check (correct_option in ('A', 'B', 'C', 'D')),
  explanation text,
  category text,
  difficulty text,
  created_at timestamp with time zone default now()
);

create unique index if not exists questions_seed_hash_idx
on public.questions ((md5(question_text || option_a || option_b || option_c || option_d)));

insert into public.questions (
  question_text,
  option_a,
  option_b,
  option_c,
  option_d,
  correct_option,
  explanation,
  category,
  difficulty
) values
  ('Una puérpera de 26 años, con parto vaginal hace 3 días, pregunta a la enfermera cuánto tiempo durará su recuperación. ¿Cuál es la duración convencionalmente aceptada del puerperio?', 'De 7 a 10 días', 'De 2 a 3 semanas', 'De 4 a 6 semanas', 'De 10 a 12 semanas', 'C', 'El puerperio se define como el periodo posterior al parto durante el cual los cambios anatómicos y fisiológicos inducidos por el embarazo revierten al estado no gestacional. Su duración no tiene límites precisos, pero convencionalmente se consideran cuatro a seis semanas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La coordinadora del servicio reorganiza el seguimiento posparto según el concepto de "cuarto trimestre". ¿Qué periodo abarca este concepto?', 'Las primeras 6 semanas posparto', 'Las primeras 8 semanas posparto', 'Las primeras 12 semanas posparto', 'Los primeros 6 meses posparto', 'C', 'El ACOG formuló el concepto de "cuarto trimestre" para reforzar la importancia de las 12 semanas posteriores al nacimiento, con una valoración integral de los aspectos físicos, sociales y psicológicos del bienestar materno.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Al egreso, la enfermera agenda el control posparto. Según el modelo de atención del cuarto trimestre, ¿cuándo se recomienda la consulta inicial?', 'A las 24 horas del alta', 'A las 3 semanas del parto', 'A las 6 semanas del parto', 'A las 12 semanas del parto', 'B', 'Se recomienda una consulta inicial a las tres semanas del parto y una consulta integral final a la duodécima semana, programando controles intermedios según necesidad (hipertensión crónica, diabetes, cardiopatía, depresión).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Se realiza seguimiento ecográfico de la involución uterina. ¿Cuál es el peso aproximado del útero a la cuarta semana posparto?', '500 g', '300 g', '100 g', '50 g', 'C', 'El útero pesa alrededor de 1 000 g inmediatamente después del parto, cerca de 500 g a la semana, 300 g a las dos semanas y completa su involución hacia la cuarta semana con un peso aproximado de 100 g.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera de 30 años, día 12 posparto, refiere secreción vaginal blanco-amarillenta, sin olor fétido ni fiebre. ¿Cómo debe registrar la enfermera este hallazgo?', 'Loquios rubra', 'Loquios serosa', 'Loquios alba', 'Metrorragia puerperal', 'C', 'Poco después del décimo día, por la mezcla de leucocitos y la reducción del contenido líquido, los loquios adoptan un tono blanco o blanco-amarillento (loquios alba). Es un hallazgo fisiológico en ausencia de fiebre, dolor o mal olor.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Cuál es la duración promedio de la descarga loquial en la puérpera normal?', 'De 7 a 10 días', 'De 14 a 20 días', 'De 24 a 36 días', 'De 45 a 60 días', 'C', 'La duración promedio de la descarga loquial varía de 24 a 36 días. Por su componente leucocitario esperado, el estudio microscópico de los loquios rara vez es informativo ante sospecha de metritis.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Multípara de 34 años, día 2 posparto, refiere dolor cólico en hipogastrio que se intensifica cada vez que amamanta. ¿Cuál es la explicación fisiológica correcta?', 'Infección uterina puerperal incipiente', 'Liberación de oxitocina que induce contracciones uterinas (entuertos)', 'Retención de fragmentos placentarios', 'Distensión vesical por retención urinaria', 'B', 'En multíparas el útero se contrae de forma vigorosa e intermitente, produciendo entuertos que se acentúan durante el amamantamiento, probablemente por la liberación de oxitocina. Son más pronunciados a mayor paridad y disminuyen hacia el tercer día.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿En cuánto tiempo se completa la extrusión (exfoliación) del sitio placentario?', 'En 1 semana', 'En 2 semanas', 'En 4 semanas', 'En 6 semanas', 'D', 'La extrusión completa del sitio placentario tarda hasta seis semanas. Inmediatamente tras el parto mide aproximadamente el tamaño de la palma de la mano y hacia el final de la segunda semana mide 3 a 4 cm.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera de 28 años, día 20 posparto, con loquios prolongados y sangrado irregular. En la exploración bimanual el útero está más grande y blando de lo esperado, sin fiebre. ¿Cuál es la sospecha diagnóstica principal?', 'Endometriosis puerperal', 'Subinvolución uterina', 'Prolapso uterino', 'Diastasis de rectos', 'B', 'La subinvolución se caracteriza por loquios prolongados y sangrado uterino irregular o excesivo, con un útero más grande y blando de lo esperado a la exploración bimanual. Se debe a conversión inadecuada de las arterias espirales, retención de fragmentos placentarios o infección.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En el caso anterior, el manejo conservador descrito por los autores del texto incluye:', 'Metilergonovina 0.2 mg VO cada 3 a 4 horas por 24 a 48 horas', 'Legrado uterino inmediato', 'Ácido tranexámico intravenoso durante 5 días', 'Reposo absoluto sin tratamiento farmacológico', 'A', 'En el hospital de los autores el tratamiento conservador de la subinvolución se realiza con metilergonovina 0.2 mg por vía oral cada 3 a 4 horas durante 24 a 48 horas; en sangrado de inicio rápido puede combinarse metilergonovina IM con infusión de oxitocina.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Según el ACOG, la hemorragia puerperal secundaria (tardía) se define como el sangrado que ocurre:', 'En las primeras 24 horas posparto', 'Entre las 24 horas y las 12 semanas posparto', 'Entre el día 7 y el día 42 posparto', 'Después de los 6 meses posparto', 'B', 'El ACOG define la hemorragia puerperal secundaria como el sangrado que se presenta entre las 24 horas y las 12 semanas posteriores al parto. Suele deberse a involución anormal del sitio placentario y afecta a cerca del 1 % de las mujeres.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera con analgesia epidural, 5 horas posparto, no ha orinado y presenta globo vesical palpable. ¿Cuál es la conducta correcta?', 'Esperar otras 4 horas y reevaluar', 'Colocar sonda vesical permanente y mantenerla al menos 24 horas', 'Realizar sondaje intermitente único y retirar de inmediato', 'Administrar diurético de asa', 'B', 'Si la mujer no orina en las 4 horas posteriores al parto, es probable que no pueda hacerlo. Ante vejiga sobredistendida se coloca sonda permanente y se mantiene al menos 24 horas, lo que evita la recurrencia y permite recuperar el tono y la sensibilidad vesical.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Tras retirar la sonda se realiza prueba de micción. A las 4 horas se mide un residuo vesical por ecografía de 260 mL. ¿Qué significa este hallazgo?', 'Vaciamiento adecuado; se continúa la vigilancia clínica', 'La vejiga no funciona correctamente; se recoloca la sonda por 24 horas', 'Indicación de cistoscopia urgente', 'Indicación de antibioticoterapia prolongada', 'B', 'Si tras la prueba de micción se obtienen más de 200 mL, la vejiga no está funcionando correctamente: se reemplaza la sonda y se mantiene otras 24 horas. Con menos de 200 mL se retira la sonda y se vigila clínica y ecográficamente.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera afebril, día 1 posparto, con recuento leucocitario de 22 000/µL a expensas de granulocitos. ¿Cómo interpreta este resultado?', 'Hallazgo fisiológico del puerperio inmediato', 'Signo inequívoco de endometritis', 'Indicación de hemocultivos seriados', 'Reacción adversa a la oxitocina', 'A', 'Durante y después del parto son posibles leucocitosis y trombocitosis marcadas. El recuento rara vez supera los 25 000/µL y el aumento se debe sobre todo a granulocitos, con linfopenia relativa y eosinopenia absoluta.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Hasta qué momento persiste el riesgo aumentado de trombosis venosa profunda y embolia pulmonar relacionado con el embarazo?', 'Hasta las 48 horas posparto', 'Hasta la primera semana posparto', 'Hasta las 12 semanas posparto', 'Hasta los 6 meses posparto', 'C', 'El fibrinógeno plasmático se mantiene elevado al menos la primera semana y contribuye a la hipercoagulabilidad, por lo que los riesgos de trombosis venosa profunda y embolia pulmonar persisten durante las 12 semanas posteriores al parto. La deambulación temprana es una medida preventiva clave.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La diuresis posparto constituye la reversión fisiológica de la retención de sodio y agua del embarazo. ¿Qué pérdida de peso ocasiona por sí misma?', 'De 0.5 a 1 kg', 'De 2 a 3 kg', 'De 5 a 6 kg', 'De 7 a 8 kg', 'B', 'La diuresis posparto produce una pérdida de peso relativamente rápida de 2 a 3 kg, que se suma a los 5 a 6 kg derivados del parto y la pérdida sanguínea normal. La pérdida de peso alcanza su máximo al final de la segunda semana.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Una madre pregunta por qué su leche es amarilla y espesa al segundo día. Respecto del calostro, es correcto afirmar que:', 'Contiene más azúcar y grasa que la leche madura', 'Es rico en inmunoglobulina A y se secreta durante 5 a 14 días', 'Carece de valor inmunológico y debe complementarse', 'Se convierte en leche madura en 48 horas', 'B', 'El calostro es rico en componentes inmunológicos, minerales y aminoácidos, con más proteínas pero menos azúcar y grasa que la leche madura. Su contenido de IgA protege al recién nacido frente a patógenos entéricos. Se secreta durante 5 a 14 días, con conversión gradual a leche madura en 4 a 6 semanas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Qué vitamina es prácticamente nula en la leche materna, motivo por el cual se administra una dosis intramuscular al recién nacido?', 'Vitamina A', 'Vitamina C', 'Vitamina K', 'Vitamina B12', 'C', 'En la leche materna se encuentran cantidades variables de casi todas las vitaminas, pero la vitamina K es virtualmente nula, por lo que se administra una dosis intramuscular al recién nacido. El contenido de vitamina D es bajo y se recomienda su complementación.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La proporción suero:caseína de la leche materna humana, considerada ideal para la absorción, es:', '20:80', '40:60', '60:40', '80:20', 'C', 'La leche materna tiene una proporción de suero (whey) a caseína de 60:40, considerada ideal para la absorción. El suero contiene grandes cantidades de interleucina-6 y otras quimiocinas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Una mujer con antecedente de necrosis hipofisaria posparto (síndrome de Sheehan) no logra lactar. ¿Cuál es la causa fisiológica?', 'Ausencia de prolactina, hormona esencial para la lactancia', 'Exceso de dopamina placentaria', 'Persistencia de valores altos de progesterona', 'Falta de receptores de oxitocina en la areola', 'A', 'La prolactina es esencial para la lactancia y las mujeres con necrosis hipofisaria extensa (síndrome de Sheehan) no lactan. Cada acto de amamantamiento eleva las concentraciones de prolactina al restringir la liberación hipotalámica de dopamina (factor inhibidor de la prolactina).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El reflejo de eyección o "descenso" de la leche es activado principalmente por la succión y puede inhibirse por el miedo o el estrés materno. ¿Qué hormona lo media?', 'Prolactina', 'Oxitocina', 'Estrógeno', 'Lactógeno placentario', 'B', 'La hipófisis posterior secreta oxitocina de forma pulsátil, provocando la contracción de las células mioepiteliales de alveolos y conductos lácteos. El reflejo puede desencadenarse incluso por el llanto del recién nacido e inhibirse por el miedo o el estrés materno.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Cuál de las siguientes constituye una contraindicación para la lactancia materna?', 'Infección materna por citomegalovirus', 'Infección materna por hepatitis C', 'Galactosemia del recién nacido', 'Herpes simple materno sin lesiones en las mamas', 'C', 'Son contraindicaciones: consumo de drogas ilegales o alcohol no controlado, galactosemia del recién nacido, infección por VIH, tuberculosis activa no tratada, ciertos fármacos y el tratamiento del cáncer de mama. La infección por CMV, hepatitis C o herpes simple sin lesiones mamarias no contraindica la lactancia.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera que no amamanta, día 4 posparto, con mamas tensas, dolorosas y temperatura de 37.9 °C que cede en 8 horas. ¿Cuál es la conducta correcta?', 'Iniciar antibioticoterapia por mastitis', 'Aplicar compresas frías, sostén ajustado y analgésicos orales', 'Administrar estrógenos para suprimir la lactancia', 'Extraer la leche cada 2 horas para vaciar la mama', 'B', 'La congestión mamaria alcanza su máximo entre el tercer y quinto día. El manejo incluye sostén ajustado o deportivo, compresas frías y analgésicos orales por 12 a 24 horas; no se recomiendan compuestos farmacológicos u hormonales para suprimir la lactancia. La fiebre por congestión rara vez persiste más de 4 a 16 horas, pero deben excluirse causas infecciosas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Durante las dos primeras horas posparto, ¿con qué frecuencia deben controlarse la presión arterial y el pulso?', 'Cada 5 minutos', 'Cada 15 minutos', 'Cada 30 minutos', 'Cada hora', 'B', 'Durante las dos horas posteriores al parto la presión arterial y el pulso se toman al menos cada 15 minutos. La temperatura se cuantifica cada 4 horas durante las primeras 8 horas y luego al menos cada 8 horas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Madre D-negativa no isoinmunizada cuyo recién nacido es D-positivo. ¿Qué intervención corresponde poco después del parto?', 'Vacuna contra la rubéola únicamente', '300 mcg de inmunoglobulina anti-D', 'Transfusión de plasma fresco congelado', 'Prueba de Coombs directo mensual sin tratamiento', 'B', 'La paciente D-negativa no isoinmunizada cuyo recién nacido es D-positivo recibe 300 mcg de inmunoglobulina anti-D poco después del parto. Además, las mujeres no inmunes a rubéola o varicela son candidatas a vacunación antes del alta.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En una mujer que no amamanta, la ovulación posparto ocurre en promedio a las:', '3 semanas (rango 2 a 4)', '7 semanas (rango 5 a 11)', '12 semanas (rango 10 a 14)', '18 semanas (rango 16 a 20)', 'B', 'En mujeres que no amamantan la menstruación se reinicia por lo general en 6 a 8 semanas y la ovulación ocurre en una media de siete semanas, con rango de cinco a once. Se ha descrito ovulación antes de los 28 días, por lo que la concepción es posible en el puerperio temprano.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera que amamanta y solicita anticoncepción antes del alta. ¿Qué método no afecta la calidad ni la cantidad de leche y puede iniciarse en cualquier momento del puerperio?', 'Anticonceptivos combinados de estrógeno y progestina', 'Anticonceptivos de progestina sola', 'Anillo vaginal de estrógeno', 'Parche transdérmico combinado', 'B', 'Para la mujer que amamanta, los anticonceptivos de progestina sola (píldoras, medroxiprogesterona de depósito o implantes) no afectan la calidad ni la cantidad de leche y pueden iniciarse en cualquier momento del puerperio. Los combinados probablemente reducen la cantidad de leche.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Según la normativa referida en el texto, la estancia hospitalaria establecida es de hasta:', '24 h tras parto vaginal y 48 h tras cesárea', '48 h tras parto vaginal y 96 h tras cesárea', '72 h tras parto vaginal y 120 h tras cesárea', '12 h tras parto vaginal y 48 h tras cesárea', 'B', 'Las normas establecen estancias hospitalarias de hasta 48 horas después de un parto vaginal sin complicaciones y hasta 96 horas después de una cesárea sin complicaciones. El alta anterior es aceptable en mujeres adecuadamente seleccionadas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera de 22 años, día 3 posparto, con llanto fácil, labilidad emocional y preocupación por el cuidado del recién nacido, sin ideas de daño ni pérdida de funcionalidad. ¿Cuál es la intervención inicial más apropiada?', 'Iniciar antidepresivo y suspender la lactancia', 'Anticipación, reconocimiento del cuadro y tranquilización, con reevaluación si persiste', 'Derivación urgente a hospitalización psiquiátrica', 'Restringir la visita del recién nacido para favorecer el descanso', 'B', 'La tristeza posparto suele ser leve y autolimitada en dos a tres días, aunque puede durar hasta diez. El tratamiento eficaz incluye anticipación, reconocimiento y tranquilidad; si los síntomas persisten o empeoran se valora depresión mayor.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto de la reanudación del coito tras un parto vaginal sin complicaciones, la orientación correcta es:', 'Está contraindicado hasta la sexta semana en todos los casos', 'Puede reanudarse después de dos semanas, según deseo y comodidad', 'Debe esperarse hasta el retorno de la menstruación', 'Se permite solo tras confirmar la involución uterina por ecografía', 'B', 'No hay evidencia que determine el momento de reanudar el coito, por lo que la conducta se individualiza; después de dos semanas puede reanudarse según el deseo y la comodidad. El estado hipoestrogénico puerperal disminuye la lubricación, lo que puede manejarse con lubricantes o estrógeno tópico.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera de 24 años, día 2 posparto vaginal, con temperatura axilar de 38.2 °C. ¿Qué valor define la fiebre puerperal?', '37.5 °C o mayor', '38 °C o mayor', '38.5 °C o mayor', '39 °C o mayor', 'B', 'La fiebre puerperal se define por una temperatura de 38 °C o mayor. Con esta definición conservadora, solo el 20 % de las mujeres febriles en las primeras 24 horas tras parto vaginal se diagnostica luego con infección pélvica, frente al 70 % de las sometidas a cesárea.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera con temperatura de 39.5 °C dentro de las primeras 24 horas posparto, con marcada afectación del estado general. ¿Qué agente debe sospecharse de forma prioritaria?', 'Estreptococo del grupo A', 'Escherichia coli', 'Ureaplasma urealyticum', 'Gardnerella vaginalis', 'A', 'La fiebre mayor de 39 °C en las primeras 24 horas del puerperio puede relacionarse con una infección pélvica virulenta secundaria a estreptococos del grupo A, cuadro potencialmente letal que puede acompañarse de síndrome de choque tóxico.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Mujer que no amamanta, día 3 posparto, con mamas tensas y temperatura de 38.3 °C que se resuelve en 10 horas. ¿Cuál es la interpretación más probable?', 'Mastitis supurativa incipiente', 'Fiebre por congestión mamaria', 'Pielonefritis aguda', 'Tromboflebitis pélvica séptica', 'B', 'Cerca del 15 % de las mujeres que no amamantan desarrolla fiebre por congestión mamaria. Esta "fiebre mamaria" rara vez supera los 39 °C en los primeros días y casi siempre dura menos de 24 horas; su incidencia es menor en quienes amamantan.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera de cesárea con anestesia general, día 1 postoperatorio, con fiebre y disminución del murmullo vesicular en bases. ¿Cuál es la medida preventiva más adecuada para la causa sospechada?', 'Antibioticoterapia profiláctica prolongada', 'Reposo absoluto en decúbito supino', 'Tos y respiración profunda en un horario fijo tras la cirugía', 'Restricción hídrica', 'C', 'La atelectasia tras anestesia general para cesárea es consecuencia de hipoventilación y se previene mejor con tos y respiración profunda en un horario fijo después de la cirugía. La fiebre asociada se debe a la proliferación de flora normal distal a los tapones mucosos.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Cuál es el factor de riesgo más importante para la aparición de infección uterina puerperal?', 'La paridad de la mujer', 'El peso del recién nacido', 'La edad gestacional al nacimiento', 'La vía del parto', 'D', 'La vía del parto es el factor de riesgo más importante para la infección uterina. Las tasas de rehospitalización por metritis y complicaciones de la herida son más altas tras cesárea, y la mortalidad relacionada con infección es notablemente mayor por esta vía.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En mujeres con parto vaginal, membranas rotas, trabajo de parto prolongado y múltiples tactos vaginales, la incidencia de metritis asciende a:', '25 % a 30 %', '13 % a 15 %', '5 % a 6 %', '1 % a 2 %', 'C', 'Con parto vaginal la incidencia de metritis es de 1 % a 2 %, pero se eleva a 5 % a 6 % ante membranas rotas, trabajo de parto prolongado y múltiples estudios cervicales. Con corioamnionitis intraparto el riesgo de infección uterina persistente supera el 13 %.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El término inclusivo preferido para designar la infección uterina puerperal que compromete decidua, miometrio y tejidos parametriales es:', 'Metritis con celulitis pélvica', 'Endometritis puerperal', 'Endoparametritis aislada', 'Corioamnionitis tardía', 'A', 'Después del parto la infección afecta no solo a la decidua, sino también al miometrio y a los tejidos parametriales, por lo que se prefiere el término inclusivo metritis con celulitis pélvica.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto de la microbiología de las infecciones pélvicas puerperales, es correcto afirmar que:', 'Son monomicrobianas y de origen nosocomial en la mayoría de los casos', 'Son polimicrobianas y derivan de bacterias endógenas del aparato genital', 'Se deben casi siempre a Neisseria gonorrhoeae', 'Se originan por contaminación hematógena a partir de foco urinario', 'B', 'La mayor parte de las infecciones pélvicas es efecto de bacterias endógenas del aparato genital y casi todas son polimicrobianas, lo que favorece la sinergia bacteriana. Los hematomas y el tejido desvitalizado incrementan la virulencia.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Una residente solicita cultivos cervicovaginales de rutina antes de iniciar tratamiento en una puérpera con metritis. ¿Cuál es la respuesta correcta?', 'Son indispensables para dirigir el tratamiento inicial', 'Deben repetirse cada 48 horas hasta la defervescencia', 'Tienen poco uso clínico e incrementan los costos; el tratamiento es empírico', 'Sustituyen a los hemocultivos en todos los casos', 'C', 'Los cultivos sistemáticos del aparato genital obtenidos antes del tratamiento representan poco uso clínico e incrementan los costos. Los hemocultivos rara vez modifican la atención; la excepción son las elevaciones muy altas de temperatura, que pueden indicar infección virulenta por estreptococos del grupo A.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Cuál es el criterio más importante para el diagnóstico de metritis puerperal?', 'La leucocitosis', 'El olor de los loquios', 'La velocidad de sedimentación globular', 'La fiebre', 'D', 'La fiebre es el criterio más importante para el diagnóstico de metritis y se presupone proporcional a la extensión de la infección. Las temperaturas suelen ser de 38 a 39 °C; las mayores de 39 °C sugieren bacteriemia o endotoxemia.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Una estudiante afirma que los loquios malolientes confirman el diagnóstico de metritis. ¿Cuál es la afirmación correcta?', 'Muchas mujeres tienen loquios malolientes sin infección y viceversa', 'Es un signo patognomónico de metritis', 'Aparece solo en infecciones por anaerobios estrictos', 'Su ausencia descarta la infección uterina', 'A', 'Aunque puede desarrollarse un olor desagradable, muchas mujeres tienen loquios malolientes sin evidencia de infección y viceversa. Algunas infecciones, en especial por estreptococos β-hemolíticos del grupo A, cursan con loquios escasos e inodoros.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El régimen considerado norma de referencia para el tratamiento de la infección pélvica posterior a cesárea es:', 'Ampicilina más gentamicina', 'Clindamicina más gentamicina', 'Penicilina G más metronidazol', 'Vancomicina en monoterapia', 'B', 'La combinación de clindamicina más gentamicina alcanzó una tasa de respuesta del 95 % y sigue considerándose la norma de referencia frente a la cual se miden otros regímenes en las infecciones pélvicas posteriores a cesárea.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera de cesárea en tratamiento con clindamicina-gentamicina, con cultivos persistentemente positivos para enterococo y sin respuesta a las 72 horas. ¿Qué antibiótico debe añadirse?', 'Ceftriaxona', 'Metronidazol', 'Ampicilina', 'Trimetoprim-sulfametoxazol', 'C', 'A pesar del régimen habitual, los cultivos de enterococos pueden mantenerse positivos. Se añade ampicilina, ya sea de forma inicial o tras 48 a 72 horas si no hay respuesta.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿En qué plazo se espera la mejoría clínica en la mayoría de las mujeres tratadas por metritis con antibióticos intravenosos de amplio espectro?', 'En 12 a 24 horas', 'En 48 a 72 horas', 'En 5 a 7 días', 'En 10 a 14 días', 'B', 'La mejoría ocurre en 48 a 72 horas en cerca del 90 % de las mujeres tratadas. La fiebre persistente después de este intervalo obliga a buscar causas de infección pélvica resistente.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Persiste la fiebre al cuarto día de tratamiento antimicrobiano intravenoso. ¿Cuál de las siguientes NO corresponde a las causas que deben investigarse?', 'Flemón parametrial', 'Absceso pélvico o hematoma infectado', 'Tromboflebitis pélvica séptica', 'Involución uterina fisiológica acelerada', 'D', 'Ante fiebre persistente deben buscarse flemón parametrial, área de celulitis intensa, absceso abdominal o pélvico, hematoma infectado y tromboflebitis pélvica séptica. En la experiencia de los autores, la resistencia bacteriana rara vez es la causa.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera tratada por metritis, afebril desde hace 26 horas y con buen estado general. ¿Cuál es la conducta al alta?', 'Egreso sin antibioticoterapia oral adicional', 'Egreso con antibiótico oral por 7 días adicionales', 'Mantener hospitalización 72 horas más', 'Egreso con anticoagulación profiláctica', 'A', 'La paciente puede ser dada de alta tras permanecer afebril al menos 24 horas y no se requiere antibioticoterapia oral adicional.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto de la profilaxis antimicrobiana en la cesárea, es correcto que:', 'Solo se indica en la cesárea de urgencia', 'Se recomienda una dosis única de antibióticos perioperatorios para todas las mujeres sometidas a cesárea', 'Debe mantenerse durante 48 horas postoperatorias', 'Está contraindicada si hubo corioamnionitis', 'B', 'Se recomienda una dosis única de antibióticos perioperatorios para todas las mujeres sometidas a cesárea, tanto electiva como no electiva. Esta práctica reduce el riesgo de infección pélvica puerperal en un 65 % a 75 %.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Gestante con índice de masa corporal de 42 programada para cesárea. Respecto de la dosis profiláctica de cefazolina, la evidencia apoya:', '4 g', '3 g', '2 g', '1 g', 'B', 'La profilaxis de dosis única con 2 g de una cefalosporina de primera generación es la pauta ideal; en mujeres obesas la evidencia apoya una dosis de 3 g de cefazolina para alcanzar concentraciones tisulares óptimas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Cuál es el antiséptico de elección para la preparación de la piel abdominal antes de la cesárea?', 'Yodopovidona acuosa', 'Alcohol etílico al 70 %', 'Clorhexidina-alcohol', 'Peróxido de hidrógeno', 'C', 'La preparación de la piel con clorhexidina-alcohol es superior al yodo-alcohol para la prevención de infecciones del sitio quirúrgico. Puede añadirse beneficio con limpieza vaginal preoperatoria con yodopovidona o gel de metronidazol.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Mujer con laceración perineal de cuarto grado reparada tras parto vaginal. Según el ACOG, la conducta basada en evidencia es:', 'No administrar antibióticos', 'Administrar antibióticos intravenosos por 72 horas', 'Administrar antibióticos orales por 10 días', 'Administrar una dosis única de antibiótico', 'D', 'El ACOG concluyó, con base en evidencia, que una sola dosis de antibiótico es razonable en las laceraciones perineales de tercer y cuarto grados. No hay datos suficientes que respalden profilaxis en el parto vaginal espontáneo o la reparación de toda episiotomía.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera de cesárea que inicia fiebre al cuarto día postoperatorio, con herida eritematosa y drenaje purulento. ¿Cuál es el tratamiento correcto?', 'Antibióticos, drenaje quirúrgico y desbridamiento del tejido desvitalizado', 'Antibióticos orales ambulatorios y observación', 'Compresas calientes y retiro parcial de las grapas', 'Cierre primario inmediato bajo anestesia local', 'A', 'Los abscesos incisionales causan fiebre persistente o de inicio alrededor del cuarto día, con herida eritematosa que drena pus. El tratamiento incluye antibióticos, drenaje quirúrgico y desbridamiento del tejido desvitalizado, revisando la integridad de la aponeurosis.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En el cuidado local posterior al desbridamiento de una herida abdominal infectada, el tejido de granulación sano que permite el cierre secundario aparece de manera característica a los:', '1 a 2 días', '4 a 6 días', '10 a 12 días', '20 a 25 días', 'B', 'El cuidado local se realiza dos veces al día; a los cuatro a seis días se presenta de manera característica tejido de granulación sano y puede efectuarse el cierre en bloque de la pared abdominal. Las suturas suelen retirarse hacia el día 10.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La dehiscencia de la aponeurosis después de una cesárea se presenta habitualmente:', 'Después de la sexta semana', 'Entre las semanas 3 y 4', 'Entre los días 7 y 10 postoperatorios', 'En las primeras 24 horas', 'C', 'La dehiscencia de la aponeurosis se presenta por lo general en los primeros siete a diez días postoperatorios. La interrupción superficial de la capa subcutánea con fuga extensa de líquido peritoneal o drenaje purulento es indicativa; constituye una urgencia quirúrgica.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera de cesárea, día 4, con dolor desproporcionado, necrosis cutánea y deterioro sistémico rápido. Se sospecha fascitis necrosante. ¿Cuál es el pilar del tratamiento?', 'Antibioticoterapia intravenosa aislada', 'Desbridamiento quirúrgico completo con márgenes amplios de tejido sano', 'Curaciones con presión negativa como medida única', 'Oxigenoterapia hiperbárica exclusiva', 'B', 'El tratamiento exitoso incluye diagnóstico temprano, control del foco mediante desbridamiento quirúrgico completo con márgenes amplios de tejido sangrante sano, antimicrobianos y cuidados intensivos. La muerte es casi ineludible sin cirugía y la mortalidad se aproxima al 50 % incluso con desbridamiento exhaustivo.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En la peritonitis puerperal, la enfermera debe considerar que:', 'La rigidez abdominal siempre es marcada y precoz', 'El primer signo es invariablemente la hipotensión', 'La rigidez puede no ser prominente por la laxitud fisiológica de la pared abdominal', 'El dolor está característicamente ausente', 'C', 'La rigidez abdominal puede no ser prominente en la peritonitis puerperal debido a la laxitud fisiológica de la pared abdominal del embarazo. El dolor puede ser intenso, pero los primeros síntomas suelen ser los del íleo adinámico, con distensión intestinal marcada.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera de cesárea con fiebre que persiste más de 72 horas pese a antimicrobianos intravenosos y masa indurada unilateral palpable en la base del ligamento ancho. ¿Cuál es el diagnóstico más probable?', 'Absceso ovárico', 'Trombosis de vena renal', 'Hematoma subaponeurótico', 'Flemón parametrial', 'D', 'El flemón parametrial es un área de induración por celulitis intensa dentro de las fibras del ligamento ancho. Se considera cuando la fiebre persiste más de 72 horas pese al tratamiento intravenoso; suele ser unilateral y la fiebre desaparece en cinco a siete días con antimicrobianos de amplio espectro.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera con metritis que mejora sintomáticamente con antimicrobianos, pero mantiene fiebre al quinto día, con escalofríos ocasionales y sin otros hallazgos. La tomografía muestra trombo en la vena ovárica derecha. ¿Cuál es la afirmación correcta sobre el manejo?', 'El uso de heparina es controversial y los autores la consideran innecesaria', 'La anticoagulación con heparina es obligatoria y acorta la recuperación', 'Requiere trombectomía quirúrgica inmediata', 'Debe suspenderse la antibioticoterapia', 'A', 'En la tromboflebitis pélvica séptica el tratamiento con heparina es controversial: un estudio aleatorizado no mostró que su adición acelerara la recuperación ni mejorara el resultado, y los autores la consideran innecesaria. No hay evidencia que sustente la anticoagulación a largo plazo.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera con episiotomía infectada y dehiscencia. Según el protocolo de reparación temprana, el cierre secundario se realiza cuando:', 'Han transcurrido al menos 21 días desde la dehiscencia', 'La herida presenta tejido de granulación rosado y sano y la paciente está afebril', 'Desaparece por completo el dolor local', 'Se obtiene un cultivo estéril de la herida', 'B', 'El protocolo incluye abrir la herida, retirar suturas, iniciar antimicrobianos intravenosos, baños de asiento, analgesia adecuada, frotado con yodopovidona y desbridamiento. La herida se cierra cuando presenta tejido de granulación rosado y saludable y la paciente está afebril.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En el cuidado posoperatorio tras la reparación secundaria de una dehiscencia perineal de cuarto grado, el objetivo respecto de las deposiciones es:', 'Mantener heces líquidas mediante laxantes osmóticos', 'Inducir estreñimiento durante 10 días', 'Lograr heces formadas y suaves con ablandadores', 'No intervenir sobre el hábito intestinal', 'C', 'El cuidado posoperatorio incluye cuidado local, ablandadores de heces y nada por vagina ni recto hasta la cicatrización. Las heces duras pueden abrir la herida y las líquidas filtrarse entre las suturas y reactivar la infección; el objetivo son heces formadas y suaves.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Puérpera con fiebre, confusión, exantema macular eritematoso difuso, vómito, diarrea acuosa y hemoconcentración marcada. ¿Cuál es el diagnóstico y su agente clásico?', 'Sepsis urinaria por Escherichia coli', 'Embolia de líquido amniótico', 'Reacción alérgica a betalactámicos', 'Síndrome de choque tóxico por Staphylococcus aureus (TSST-1)', 'D', 'El síndrome de choque tóxico cursa con fiebre, cefalea, confusión, exantema macular difuso, vómito, diarrea acuosa y hemoconcentración, con descamación durante la recuperación. Se aisló S. aureus en casi todos los casos iniciales; la exotoxina TSST-1 provoca lesión endotelial profunda. La mortalidad es de 10 % a 15 %.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Mujer que amamanta, día 10 posparto, con escalofríos, fiebre, taquicardia y mama derecha endurecida, enrojecida y dolorosa. Respecto de la mastitis puerperal, es correcto que:', 'Es casi invariablemente unilateral y rara vez aparece antes del final de la primera semana', 'Suele ser bilateral y aparecer en las primeras 48 horas', 'Obliga a suspender la lactancia de ambas mamas', 'Se diagnostica únicamente por hemocultivo', 'A', 'La incidencia de mastitis puerperal se aproxima al 3 %. Los síntomas rara vez aparecen antes del final de la primera semana; la infección es unilateral casi de forma invariable y suele precederla congestión marcada. Cerca del 10 % desarrolla absceso.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En el caso anterior, el tratamiento empírico inicial habitual y su duración recomendada son:', 'Amoxicilina 500 mg VO cada 8 h por 3 días', 'Dicloxacilina 500 mg VO cada 6 h durante 10 días', 'Ceftriaxona 1 g IM dosis única', 'Metronidazol 500 mg VO cada 12 h por 5 días', 'B', 'Puede iniciarse dicloxacilina 500 mg por vía oral cada 6 horas de modo empírico; en alérgicas a la penicilina se usa eritromicina, y ante sospecha de patógenos resistentes, vancomicina, clindamicina o trimetoprim-sulfametoxazol. Aunque la respuesta puede ser rápida, se recomienda tratamiento durante 10 días.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Una madre con mastitis pregunta si debe suspender la lactancia. La orientación correcta, con base en la evidencia citada, es:', 'Suspender la lactancia hasta completar el tratamiento', 'Continuar amamantando; el abandono se asocia a mayor formación de abscesos', 'Alimentar solo con la mama afectada', 'Suspender la lactancia únicamente si la fiebre supera 38.5 °C', 'B', 'Se demostró la importancia de continuar la lactancia: de 65 mujeres con mastitis, las tres que desarrollaron abscesos pertenecían al grupo de 15 que dejó de amamantar. La extracción vigorosa de leche puede ser tratamiento suficiente; al amamantar de forma bilateral conviene iniciar por la mama no afectada.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Cuándo debe sospecharse un absceso mamario en una puérpera con mastitis en tratamiento?', 'Si aparece dolor al amamantar', 'Únicamente si hay fluctuación evidente', 'Si la fiebre no cede en 48 a 72 horas o se palpa una masa', 'Si el cultivo de leche resulta positivo', 'C', 'Debe sospecharse absceso cuando la defervescencia no ocurre en las 48 a 72 horas posteriores al tratamiento o cuando es palpable una masa. La detección de fluctuación puede ser difícil, por lo que la ecografía suele ser diagnóstica; el tratamiento es el drenaje quirúrgico o la aspiración con aguja guiada por ecografía.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Según la GPC, el parto a término es aquel que se presenta entre las:', '20 y 28 semanas de gestación', '28 y 36 semanas de gestación', '37 y 42 semanas de gestación', 'Más de 42 semanas de gestación', 'C', 'Sección 8, Definiciones: el parto a término es el que se presenta entre las 37 y 42 semanas. Entre 20-28 semanas corresponde a parto inmaduro y entre 28-36 semanas a parto pretérmino.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El parto pretérmino o prematuro se define como aquel que ocurre entre las:', '20 y 27 semanas', '28 y 36 semanas', '34 y 36 semanas', '37 y 38 semanas', 'B', 'Sección 8, Definiciones: parto pretérmino o prematuro es el que se presenta entre las 28 y las 36 semanas de gestación.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Se considera parto postérmino aquel que se presenta luego de las 42 semanas de gestación o más de:', '274 días', '280 días', '287 días', '294 días', 'D', 'Sección 8, Definiciones: parto postérmino es el que se presenta luego de las 42 semanas o más de 294 días, calculados a partir de la FUM confiable.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El código CIE-10 correspondiente al parto único espontáneo con presentación cefálica de vértice es:', 'O80', 'O80.0', 'O80.9', 'O81.0', 'B', 'Sección 2, Clasificación CIE-10: O80 corresponde a parto único espontáneo; O80.0 a presentación cefálica de vértice; O80.9 sin otra especificación.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La fase latente del trabajo de parto se caracteriza por progresión lenta o escasa de la dilatación hasta:', '2 cm', '3 cm', '4 cm', '6 cm', 'C', 'Sección 8: la fase latente comienza con el inicio del parto, con contracciones variables en intensidad y duración, borramiento cervical y progresión lenta de la dilatación hasta 4 cm.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La fase activa del trabajo de parto comienza con una dilatación de:', 'Más de 2 cm y termina en 8 cm', 'Más de 4 cm y termina en dilatación completa (10 cm)', '6 cm y termina en 10 cm', '3 cm y termina en 8 cm', 'B', 'Sección 8: la fase activa se caracteriza por aumento en regularidad, intensidad y frecuencia de las contracciones; comienza con más de 4 cm y termina en dilatación completa de 10 cm.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La tercera etapa del trabajo de parto o alumbramiento es la que transcurre entre:', 'La dilatación completa y el nacimiento', 'El nacimiento y la expulsión de la placenta', 'La expulsión de la placenta y las 2 horas posparto', 'El inicio del pujo y el nacimiento', 'B', 'Sección 8: la tercera etapa o alumbramiento transcurre entre el nacimiento y la expulsión de la placenta.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La población blanco de esta Guía de Práctica Clínica corresponde a:', 'Todas las mujeres embarazadas del país', 'Mujeres embarazadas de bajo riesgo en trabajo de parto', 'Mujeres con embarazo de alto riesgo obstétrico', 'Puérperas con complicaciones hemorrágicas', 'B', 'Sección 1, Descripción de la GPC: la población blanco son las mujeres embarazadas de bajo riesgo en trabajo de parto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La duración aproximada de la fase latente del trabajo de parto es de:', '6,4 horas en nulíparas y 4,8 horas en multíparas', '8 horas en nulíparas y 5 horas en multíparas', '4,8 horas en nulíparas y 6,4 horas en multíparas', '12 horas en nulíparas y 8 horas en multíparas', 'A', 'Fase latente del trabajo de parto (E-1a): la duración es de aproximadamente 6,4 horas en la nulípara y 4,8 horas en las multíparas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Se define como distocia:', 'El parto que ocurre antes de las 37 semanas', 'El parto o alumbramiento que procede de manera anormal o difícil', 'La ausencia de dinámica uterina regular', 'La expulsión de la placenta en más de 30 minutos', 'B', 'Sección 10, Glosario de términos: distocia es el parto o alumbramiento que procede de manera anormal o difícil.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Los criterios de admisión de la embarazada en trabajo de parto en el centro obstétrico son:', 'Dinámica uterina regular, borramiento >50% y dilatación de 3-4 cm', 'Dolor abdominal, ruptura de membranas y dilatación de 2 cm', 'Contracciones irregulares, borramiento <50% y dilatación de 2 cm', 'Dinámica uterina regular, borramiento completo y dilatación de 6 cm', 'A', 'Admisión o momento del ingreso al centro obstétrico (E-4): los criterios son dinámica uterina regular, borramiento cervical mayor al 50% y dilatación de 3-4 cm, es decir, que se encuentre en fase activa del parto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La admisión hospitalaria de forma temprana o durante la fase latente NO se recomienda porque:', 'Aumenta la mortalidad materna comprobada', 'Se asocia a mayor intervencionismo durante el parto', 'Disminuye la satisfacción del personal de salud', 'Incrementa la duración de la fase latente', 'B', 'E-3: no se recomienda la admisión temprana o en fase latente por asociarse a mayor intervencionismo (uso de oxitocina, analgesia epidural e intubaciones en neonatos); la evidencia sobre morbimortalidad aún es insuficiente.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Una embarazada acude por contracciones dolorosas, presenta 2 cm de dilatación, sin dinámica uterina regular y borramiento del 40%. Vive en el área urbana, cerca del servicio, y está hemodinámicamente estable. La conducta recomendada es:', 'Ingreso inmediato e inicio de oxitocina', 'Ingreso para monitorización fetal electrónica continua', 'Retorno al domicilio con orientación adecuada y signos de alarma', 'Realizar amniotomía para acelerar el trabajo de parto', 'C', 'Punto de buena práctica (R-P): se indica retorno al domicilio con adecuada orientación cuando hay menos de 3 cm de dilatación, sin dinámica uterina regular, borramiento <50%, estabilidad hemodinámica, sin antecedentes de gran multiparidad o partos rápidos, y vive en área urbana de fácil acceso.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Cuál de los siguientes antecedentes justifica un ingreso temprano de la paciente aun sin estar en fase activa?', 'Primigesta con embarazo controlado que vive a 10 minutos del hospital', 'Paciente que acude desde el área rural, a más de una hora del centro de atención', 'Paciente con temor al parto que solicita hospitalización', 'Paciente con 39 semanas y movimientos fetales normales', 'B', 'R-P: se genera un ingreso temprano en pacientes con antecedentes de multiparidad o partos rápidos, patología de base materna que debe ser controlada, o que acuden desde el área rural con difícil acceso (comunidad distante a más de una hora).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En la fase activa del trabajo de parto, el promedio de duración y el límite superior en la primípara son, respectivamente:', '5 horas y 12 horas', '8 horas y 18 horas', '6 horas y 14 horas', '10 horas y 20 horas', 'B', 'E-1a: en las primíparas el promedio de duración es de 8 horas y es poco probable que dure más de 18 horas; en las multíparas, 5 horas y poco probable más de 12 horas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El progreso de la dilatación en la fase activa está determinado en:', '1,1 cm/hora en nulíparas y 1,3 cm/hora en multíparas', '1,3 cm/hora en nulíparas y 1,1 cm/hora en multíparas', '1 cm/hora en todas las mujeres', '0,5 cm/hora en nulíparas y 1 cm/hora en multíparas', 'A', 'E-1a: en la fase activa el progreso es de 1,1 cm/hora en las mujeres nulíparas y de 1,3 cm/hora en las multíparas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Se recomienda valoración por el especialista siempre que el trabajo de parto en fase activa se prolongue más allá de:', '6 horas en la nulípara y 4 horas en la multípara', '8 horas en la nulípara y 5 horas en la multípara', '12 horas en la nulípara y 8 horas en la multípara', '18 horas en la nulípara y 12 horas en la multípara', 'B', 'R-P: se recomienda valoración por el especialista siempre que la fase activa se prolongue más allá del promedio de 8 horas en la nulípara y 5 horas en la multípara.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En condiciones normales, la frecuencia recomendada para realizar las exploraciones vaginales durante el trabajo de parto es cada:', '1 hora', '2 horas', '4 horas', '6 horas', 'C', 'R-P: se recomienda que las exploraciones vaginales se realicen cada cuatro horas en condiciones normales.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Tras la rotura prematura de membranas, el factor independiente más importante para predecir infección materna y/o neonatal es:', 'El tiempo transcurrido desde la rotura', 'El número de tactos vaginales realizados', 'El uso de oxitocina', 'La posición materna durante el trabajo de parto', 'B', 'E-2a: el número de tactos vaginales en el manejo de la primera etapa del trabajo de parto, tras la rotura prematura de membranas, es el factor independiente más importante para predecir una infección materna y/o neonatal.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto al partograma, la GPC recomienda utilizar la línea de acción de:', 'Dos horas', 'Tres horas', 'Cuatro horas', 'Seis horas', 'C', 'R-A: si se utiliza, se recomienda el partograma de una línea de acción de cuatro horas, dándose más tiempo antes de emprender alguna acción por retardo de la dilatación. Las líneas de tres horas incrementan el número de cesáreas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto al uso del enema durante el trabajo de parto, la recomendación es:', 'Aplicarlo de rutina a toda paciente al ingreso', 'Aplicarlo solo en multíparas', 'No utilizarlo de forma rutinaria durante el parto', 'Aplicarlo únicamente antes de la episiotomía', 'C', 'R-A: no se recomienda utilizar el enema de forma rutinaria durante el parto; su uso no reduce las tasas de infección materna o neonatal, ni las dehiscencias de episiotomía, ni mejora la satisfacción materna.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En relación con el rasurado perineal sistemático en mujeres en trabajo de parto:', 'Se recomienda en todas las pacientes por asepsia', 'No se recomienda de forma sistemática', 'Se recomienda solo si se prevé episiotomía', 'Se recomienda solo en pacientes con cesárea previa', 'B', 'R-B: no se recomienda el rasurado perineal sistemático. No existen pruebas suficientes sobre su efectividad; incluso se observó menor colonización bacteriana Gram negativa en las mujeres a las que no se les realizó.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Sobre la ingesta durante el trabajo de parto, la GPC recomienda:', 'Ayuno absoluto por riesgo de síndrome de Mendelson', 'Permitir la ingesta de líquidos claros o bebidas isotónicas', 'Permitir únicamente agua en pequeños sorbos', 'Permitir dieta completa en todas las pacientes', 'B', 'R-A: se recomienda permitir la ingesta de líquidos claros (agua, zumos de frutas sin pulpa, café y té sin leche) o bebidas isotónicas durante el parto; esto mejora el confort y la satisfacción materna sin incrementar las complicaciones.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Las bebidas isotónicas son preferibles a la ingesta de agua durante el trabajo de parto porque:', 'Aceleran la dilatación cervical', 'Combaten la cetosis', 'Disminuyen el riesgo de hemorragia posparto', 'Reducen la necesidad de analgesia epidural', 'B', 'R-A: se recomienda informar a las mujeres sobre la eficacia de las bebidas isotónicas para combatir la cetosis durante el trabajo de parto, por lo que son preferibles a la ingesta de agua.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Cuál de los siguientes NO corresponde a uno de los cinco momentos de la higiene de manos?', 'Antes de tocar a la paciente', 'Antes de realizar una tarea de limpieza aséptica', 'Después del contacto con el entorno de la paciente', 'Antes de retirarse el equipo de protección personal', 'D', 'R-A: los cinco momentos son: antes de tocar a la paciente; antes de realizar una tarea de limpieza aséptica; después del riesgo de exposición a líquidos corporales; después de tocar a la paciente; y después del contacto con el entorno de la paciente.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En partos vaginales que progresan de forma normal, la amniotomía/amniorrexis artificial y la perfusión de oxitocina:', 'Se recomiendan de rutina para acortar el trabajo de parto', 'NO se recomiendan de forma rutinaria', 'Se recomiendan solo en nulíparas', 'Se recomiendan al alcanzar los 6 cm de dilatación', 'B', 'R-A: NO se recomienda realizar amniotomía/amniorrexis artificial ni perfusión de oxitocina de forma rutinaria en partos vaginales que progresan de forma normal, ya que las pruebas muestran que esto no mejora los resultados.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Según el esquema de oxitocina a dosis baja recomendado en Ecuador para alteraciones de la duración y progreso del trabajo de parto, la dilución es:', '500 cc de SS 0,9% más 5 UI de oxitocina', '1.000 cc de SS 0,9% más 10 UI de oxitocina', '1.000 cc de dextrosa al 5% más 20 UI de oxitocina', '500 cc de lactato Ringer más 10 UI de oxitocina', 'B', 'R-P: el esquema de oxitocina a dosis baja utiliza 1.000 cc de SS 0,9% más 10 UI de oxitocina, con dosis inicial de 1 mU/min (6 ml/h) en bomba de infusión.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En el esquema de oxitocina a dosis baja con bomba de infusión, el intervalo para duplicar la dosis y la dosis máxima son:', 'Cada 15 minutos, hasta 20 mU/min', 'Cada 30 minutos, hasta 30 mU/min (180 ml/h)', 'Cada 60 minutos, hasta 40 mU/min', 'Cada 30 minutos, hasta 60 mU/min', 'B', 'R-P: se dobla la dosis hasta conseguir dinámica eficaz, con intervalo de 30 minutos y dosis máxima de 30 mU/min (180 ml/h) en bomba de infusión.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto a la posición de la embarazada durante el trabajo de parto, la GPC recomienda:', 'Decúbito supino obligatorio para vigilancia fetal', 'Posición de litotomía desde la fase activa', 'Libre posición, incluso en quienes usan analgesia epidural', 'Deambulación obligatoria hasta los 8 cm', 'C', 'R-B: se recomienda alentar y ayudar a las mujeres a la LIBRE POSICIÓN a lo largo de la fase activa y a movilizarse si así lo desean, previa comprobación del bloqueo motor y propioceptivo, incluso a las que utilizan analgesia epidural.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto a la valoración de la frecuencia cardíaca fetal (FCF) en la admisión de la embarazada de bajo riesgo:', 'La monitorización fetal electrónica continua es obligatoria', 'La auscultación fetal intermitente está contraindicada', 'No es obligatoria la MFEc; el método lo determina el profesional de salud', 'Solo se debe usar cardiotocografía en fase activa', 'C', 'R-P: no es obligatoria la realización de MFEc al ingreso de la paciente de bajo riesgo; el método de valoración de la FCF será determinado por el profesional de salud según las características del trabajo de parto y los antecedentes de la embarazada.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Cuál de las siguientes situaciones NO constituye indicación para cambiar de auscultación fetal intermitente a monitorización fetal electrónica continua?', 'Líquido amniótico teñido de meconio', 'Fiebre materna', 'Uso de oxitocina', 'Dilatación de 5 cm en multípara', 'D', 'R-P: el cambio de AFI a MFEc se realiza ante meconio, alteración del latido cardíaco fetal por auscultación, fiebre materna, sangrado durante el parto, uso de oxitocina, demanda de la mujer, y durante 30 minutos tras la anestesia epidural o cada bolo adicional.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Durante la fase activa, la auscultación fetal intermitente debe realizarse al menos cada:', '5-10 minutos, durante 15 segundos', '15-30 minutos, durante 30-60 segundos después de una contracción', '30-45 minutos, durante 60 segundos antes de la contracción', '60 minutos, durante 30 segundos', 'B', 'Anexo 3: el corazón fetal se debe auscultar al menos cada 15-30 minutos durante el período de dilatación y al menos cada 5-15 minutos en el período expulsivo; la auscultación se lleva a cabo durante 30-60 segundos como mínimo, después de una contracción.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Durante la auscultación fetal intermitente, conocer el pulso materno es necesario para:', 'Detectar hipotensión secundaria a la epidural', 'Diferenciar entre el ritmo materno y el latido cardíaco fetal', 'Calcular la variabilidad de la línea de base', 'Establecer el momento de la amniotomía', 'B', 'Anexo 3, literal b: el pulso materno también debe ser conocido para diferenciar entre el ritmo materno y el latido cardíaco fetal.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Las mujeres que reciben apoyo continuo profesional durante el trabajo de parto tienen MENOR probabilidad de:', 'Parto vaginal espontáneo', 'Tener un parto por cesárea', 'Establecer lactancia materna precoz', 'Deambular durante la fase activa', 'B', 'E-1a: las mujeres con apoyo continuo profesional tienen mayor probabilidad de parto vaginal espontáneo y menor probabilidad de recibir analgesia regional, tener parto vaginal instrumental, parto por cesárea e informar insatisfacción con la experiencia de parto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Ante un trazado de FCF de categoría III en una paciente con oxitocina en infusión, la conducta correcta es:', 'Incrementar la dosis de oxitocina y reevaluar en 30 minutos', 'Suspender la oxitocina y realizar evaluación completa del feto por especialista', 'Mantener la oxitocina y administrar oxígeno prolongado a la madre', 'Colocar a la paciente en decúbito supino', 'B', 'Anexo 4: si el trazado se clasifica como III se debe suspender la oxitocina y proceder a una evaluación completa de la condición del feto por un especialista antes de reanudar la oxitocina. Ante patrón anormal se cambia a decúbito lateral izquierdo, no supino, y se evita la oxigenoterapia prolongada.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La duración normal del período expulsivo en una nulípara SIN analgesia epidural es de hasta:', 'Una hora', 'Dos horas', 'Tres horas', 'Cuatro horas', 'C', 'E-2b: hasta tres horas para nulíparas sin analgesia epidural; hasta cuatro horas para nulíparas con epidural; hasta dos horas para multíparas sin epidural y hasta tres horas para multíparas con epidural.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La duración normal del expulsivo en una multípara CON analgesia epidural es de hasta:', 'Una hora', 'Dos horas', 'Tres horas', 'Cuatro horas', 'C', 'E-2b: para multíparas con analgesia epidural, hasta tres horas; sin analgesia epidural, hasta un máximo de dos horas.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Existe asociación demostrada entre la duración prolongada de la segunda etapa del parto y:', 'Incontinencia urinaria de esfuerzo a largo plazo', 'Hemorragia posparto y mayores índices de cesárea y partos instrumentales', 'Ictericia neonatal', 'Retención placentaria a los 10 minutos', 'B', 'E-2b: existe asociación entre la duración larga de la 2ª etapa y la presencia de hemorragia posparto, así como con altos índices de cesáreas y partos instrumentales. En cambio, el expulsivo prolongado NO se asocia a incontinencia urinaria de esfuerzo a largo plazo.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto al tipo de pujo durante el período expulsivo, la GPC recomienda:', 'El pujo dirigido en todas las pacientes', 'El pujo espontáneo, instintivo, de forma fisiológica', 'El pujo en apnea sostenida por 10 segundos', 'El pujo asistido con maniobra de Kristeller', 'B', 'R-A: se recomienda el pujo espontáneo, el instintivo de forma fisiológica; no se recomienda el pujo dirigido, que controla la intensidad y el tiempo del pujo desde la aparición espontánea de la contracción.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En mujeres con analgesia epidural, se recomienda dirigir los pujos solo cuando la presentación haya sobrepasado:', 'El primer plano de Hodge', 'El segundo plano de Hodge', 'Las espinas isquiáticas (tercer plano de Hodge)', 'El cuarto plano de Hodge', 'C', 'R-A: en mujeres con analgesia epidural se recomienda dirigir los pujos solo de ser necesario cuando la presentación haya sobrepasado las espinas isquiáticas (tercer plano de Hodge).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Las posiciones verticales o laterales durante el expulsivo, comparadas con la supina o de litotomía, se asocian a:', 'Mayor duración de la segunda etapa y más episiotomías', 'Menor duración de la segunda etapa, menos nacimientos asistidos y menos episiotomías', 'Mayor frecuencia de patrones anormales de FCF', 'Mayor necesidad de analgesia epidural', 'B', 'E-1a: las posiciones verticales o laterales se asocian a menor duración de la segunda etapa, menos nacimientos asistidos, menores tasas de episiotomía, menor dolor agudo y menos patrones anormales de la FCF.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Cuál de las siguientes intervenciones SÍ se recomienda para la prevención del trauma perineal durante la segunda etapa?', 'Masaje perineal durante el expulsivo', 'Aplicación de anestésico local en spray', 'Aplicación local de compresas calientes', 'Episiotomía mediana de rutina', 'C', 'R-A: se recomienda posibilitar la aplicación local de compresas calientes durante la 2ª etapa. No se recomienda el masaje perineal durante la segunda etapa ni el anestésico local en spray para reducir el dolor perineal.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La técnica recomendada para la protección activa del periné es:', 'Maniobra de Kristeller sincronizada', 'Deflexión controlada de la cabeza fetal', 'Presión bimanual sobre la horquilla vulvar', 'Episiotomía profiláctica en toda nulípara', 'B', 'R-B: se recomienda la protección activa del periné mediante la técnica de deflexión controlada de la cabeza fetal.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto a la episiotomía en el parto espontáneo, la evidencia indica que:', 'La episiotomía rutinaria mejora los resultados perineales a largo plazo', 'La episiotomía selectiva incrementa el número de mujeres con perineo intacto', 'La episiotomía rutinaria disminuye la necesidad de sutura perineal', 'La episiotomía debe practicarse en todas las primíparas', 'B', 'E-1a: la episiotomía selectiva frente a la sistemática incrementa el número de mujeres con perineo intacto y el número de mujeres que reanudan la vida sexual al mes, disminuye la necesidad de reparación y sutura perineal, y el número de mujeres con dolor al alta.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Cuando se realiza una episiotomía, la técnica recomendada es la mediolateral, iniciada en la comisura posterior de la vulva, dirigida habitualmente hacia el lado derecho, en un ángulo de:', '15 a 30 grados', '30 a 45 grados', '45 a 60 grados', '60 a 90 grados', 'C', 'R-D: la técnica recomendada es la episiotomía mediolateral, comenzándola en la comisura posterior de la vulva, dirigida habitualmente hacia el lado derecho en un ángulo entre 45 y 60 grados.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto a la maniobra de Kristeller durante la segunda etapa del parto, la GPC establece que:', 'Es eficaz para acortar el expulsivo y se recomienda en nulíparas', 'No se recomienda; es ineficaz y constituye factor de riesgo de morbilidad materna y fetal', 'Se recomienda solo cuando hay agotamiento materno', 'Se recomienda como alternativa al parto instrumental', 'B', 'R-A y E-1b: no se recomienda realizar la maniobra de Kristeller. No muestra diferencias en la duración de la segunda etapa, existen pruebas de que es factor de riesgo de morbilidad materna y fetal, y se concluye que es ineficaz.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El desgarro perineal que se extiende hasta el esfínter rectal corresponde al grado:', 'I', 'II', 'III', 'IV', 'C', 'Sección 10, Glosario: el desgarro grado III se extiende a todo lo anterior y al esfínter rectal; el grado IV incluye extensión a mucosa rectal, dejando descubierta la luz del recto.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En la reparación de un desgarro de segundo grado, si tras la sutura muscular la piel está bien aproximada:', 'Debe suturarse siempre con puntos discontinuos', 'No es necesario suturarla', 'Debe suturarse con sutura no absorbible', 'Debe dejarse abierta y cubrirse con apósito', 'B', 'R-A: si después de la sutura muscular de un desgarro de segundo grado la piel está bien aproximada, no es necesario suturarla; si requiere aproximación, se realiza con técnica continua o puntos discontinuos.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El material de elección para la reparación de la herida perineal es:', 'Sutura de seda no absorbible', 'Sutura sintética reabsorbible', 'Catgut simple exclusivamente', 'Grapas quirúrgicas', 'B', 'R-A: se recomienda la utilización de sutura sintética reabsorbible para la reparación de la herida perineal. El Anexo 8 especifica sutura sintética absorbible de poliglicólico/poliglactina No 2/0.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Con manejo activo, la tercera etapa del trabajo de parto se considera prolongada si no se completa en:', '10 minutos', '15 minutos', '30 minutos', '60 minutos', 'C', 'R-D: la tercera etapa se considera prolongada si no se completa en los 30 minutos posteriores al nacimiento del neonato, con manejo activo.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El manejo activo del alumbramiento comprende:', 'Uterotónico profiláctico, tracción controlada del cordón y masaje uterino tras la expulsión de la placenta', 'Expulsión de la placenta por gravedad y pujo materno', 'Extracción manual de la placenta a los 15 minutos', 'Legrado uterino instrumental posparto', 'A', 'Sección 10, Glosario y R-D: el manejo activo del alumbramiento comprende la administración profiláctica de uterotónicos, la tracción controlada del cordón umbilical y el masaje uterino tras la expulsión de la placenta. La segunda opción corresponde al manejo fisiológico.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El uterotónico y la dosis recomendados para el manejo activo del alumbramiento son:', 'Oxitocina 5 UI IV en bolo', 'Oxitocina 10 UI IM', 'Misoprostol 600 mcg vía oral', 'Metilergonovina 0,2 mg IM', 'B', 'R-A: se recomienda el manejo activo del alumbramiento con oxitocina IM 10 UI.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('A partir de qué momento del alumbramiento con manejo activo el riesgo de hemorragia posparto aumenta progresivamente con la duración:', '5 minutos', '10 minutos', '20 minutos', '30 minutos', 'B', 'E-2a: a partir de los 10 minutos de duración del alumbramiento, con manejo activo, el riesgo de hemorragia posparto aumenta progresivamente con la duración del mismo.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En la comparación entre oxitocina y derivados del ergot en el alumbramiento, se observó en el grupo de oxitocina:', 'Mayor incidencia de HPP >500 ml', 'Disminución del riesgo de extracción manual de la placenta', 'Mayor necesidad de oxitócicos adicionales', 'Mayor duración de la tercera etapa', 'B', 'Manejo del alumbramiento: no se observan diferencias entre oxitocina y derivados del cornezuelo de centeno/ergot en cuanto a la disminución de la HPP >500 ml, pero sí una disminución del riesgo de extracción manual de la placenta en el grupo de oxitocina.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Las mujeres deben ser informadas, preferiblemente durante la gestación, de que el manejo activo de la tercera etapa:', 'Aumenta la duración del alumbramiento pero reduce el dolor', 'Acorta su duración, disminuye el riesgo de HPP y la necesidad de oxitocina terapéutica', 'Evita totalmente la hemorragia posparto', 'Sustituye la necesidad de vigilancia posparto', 'B', 'R-P: las mujeres deben ser informadas (preferiblemente durante la gestación) de que el manejo activo de la tercera etapa del parto acorta su duración, disminuye el riesgo de hemorragia posparto y la necesidad de oxitocina terapéutica.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El momento recomendado para el pinzamiento del cordón umbilical es:', 'Inmediatamente después del nacimiento', 'A partir del primer minuto', 'A partir del segundo minuto o tras el cese del latido, lo que ocurra primero', 'A los cinco minutos en todos los casos', 'C', 'R-B: se recomienda el pinzamiento del cordón umbilical a partir del segundo minuto o tras el cese de su latido, lo que ocurra primero.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El pinzamiento oportuno (tardío) del cordón umbilical en neonatos a término:', 'Incrementa el riesgo de hemorragia posparto', 'Mejora los niveles de hierro en el neonato', 'Disminuye la necesidad de fototerapia', 'Reduce el tiempo de lactancia materna', 'B', 'E-1a: el pinzamiento oportuno, al menos dos minutos después del parto, no incrementa el riesgo de hemorragia posparto y mejora los niveles de hierro en neonatos. Es el pinzamiento temprano el que disminuye el número de neonatos con ictericia medido por necesidad de fototerapia.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El contacto piel con piel inmediato tras el nacimiento es beneficioso a corto plazo para:', 'Prevenir la enfermedad hemorrágica del recién nacido', 'Mantener la temperatura y disminuir el llanto del niño', 'Acelerar la expulsión de la placenta', 'Prevenir la oftalmía gonocócica', 'B', 'E-1b: el contacto piel con piel es beneficioso a corto plazo para mantener la temperatura y disminuir el llanto del niño, y a largo plazo para aumentar el tiempo de lactancia materna.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Según el Anexo 6, la temperatura confortable que debe mantenerse en la sala de partos para el contacto piel con piel es de:', '18-20 °C', '20-22 °C', '22-24 °C', '25-28 °C', 'C', 'Anexo 6, numeral 3: mantener una temperatura confortable en la sala de partos (22-24 °C).', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El Test de Apgar durante el contacto piel con piel debe realizarse:', 'En la cuna de calor radiante, separando al RN de la madre', 'Al minuto y a los 5 minutos sobre el cuerpo de la madre', 'Únicamente a los 5 minutos', 'Después del primer baño del RN', 'B', 'Anexo 6, numeral 15: realizar el Test de Apgar al minuto y a los 5 minutos sobre el cuerpo de la madre, sin interrumpir el contacto piel con piel.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La iniciación de la lactancia materna debe ser alentada preferentemente dentro de:', 'Los primeros 30 minutos', 'La primera hora de vida', 'Las primeras dos horas', 'Las primeras seis horas', 'B', 'R-A: la iniciación de la lactancia materna debe ser alentada lo antes posible después del nacimiento, preferentemente dentro de la primera hora, y debe ser realizada por la enfermera capacitada.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto al baño del recién nacido, la GPC recomienda:', 'Baño de inmersión inmediato al nacimiento', 'Primer baño al estabilizarse la temperatura, al menos después de las dos horas de nacido', 'Baño completo dentro de la primera hora', 'No bañar al RN hasta el alta hospitalaria', 'B', 'R-D: se recomienda realizar el primer baño cuando la temperatura del RN se haya estabilizado (al menos después de las dos horas de nacido), realizando solamente el lavado de la cabeza si la acumulación de sangre o secreciones lo amerita.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El baño de todo el cuerpo del recién nacido se considerará:', 'Posterior a las 6 horas del nacimiento', 'Posterior a las 12 horas del nacimiento o si la madre lo solicitare', 'Posterior a las 24 horas del nacimiento', 'Solo antes del alta hospitalaria', 'B', 'R-D: el baño de todo el cuerpo se considerará posterior a las 12 horas después del nacimiento o si la madre lo solicitare.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('No se recomienda retirar el vérnix caseoso de la piel del recién nacido porque:', 'Facilita la termorregulación exclusivamente', 'Protege al RN contra la invasión bacteriana al nacimiento', 'Mejora la adherencia del brazalete de identificación', 'Disminuye la ictericia fisiológica', 'B', 'R-C: se recomienda no quitar el vérnix de la piel, ya que este y el líquido amniótico protegen al RN contra la invasión bacteriana al nacimiento.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto a la aspiración orofaríngea y nasofaríngea sistemática del recién nacido:', 'Se recomienda en todo RN para permeabilizar la vía aérea', 'No se recomienda de forma sistemática', 'Se recomienda solo en RN a término', 'Se recomienda antes del pinzamiento del cordón', 'B', 'R-A: no se recomienda la aspiración sistemática orofaríngea ni nasofaríngea del RN. Los RN no aspirados presentan mejores resultados en el Apgar a los 5 minutos y menor tiempo para obtener SatO2 >92%.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto al paso de sonda nasogástrica y rectal en el recién nacido sano:', 'Se recomienda de rutina para descartar atresias', 'No se recomienda de forma sistemática', 'Se recomienda solo en RN pretérmino', 'Se recomienda a las 24 horas de vida', 'B', 'R-P: no se recomienda realizar el paso sistemático de sonda nasogástrica ni rectal para descartar atresias en el RN sano; se debe confirmar visualmente la presencia de ano y vigilar la eliminación de meconio durante la estancia.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El sitio indicado para medir la temperatura en el recién nacido es:', 'Rectal', 'Timpánico', 'Axilar', 'Oral', 'C', 'E-4: la región del cuerpo que más se aproxima a la temperatura interna o central es la axilar, sitio indicado para medir la temperatura en el RN. La temperatura rectal se restringe a hipotermia moderada-grave y la timpánica no está indicada.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Para la profilaxis oftálmica del recién nacido se recomienda colocar dosis única de:', 'Nitrato de plata al 1%', 'Pomada oftálmica de eritromicina al 0,5% o tetraciclina al 1%', 'Gentamicina oftálmica al 0,3%', 'Cloranfenicol oftálmico al 0,5%', 'B', 'E-2b: se recomienda dosis única de pomada oftálmica de eritromicina al 0,5% o de tetraciclina al 1%. La solución de nitrato de plata puede producir conjuntivitis química transitoria, por lo que debe evitarse.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El tiempo de administración de la profilaxis oftálmica puede ampliarse hasta:', 'Una hora tras el nacimiento', 'Dos horas tras el nacimiento', 'Cuatro horas tras el nacimiento', 'Doce horas tras el nacimiento', 'C', 'R-P: el tiempo de administración de profilaxis oftálmica puede ampliarse hasta las cuatro horas tras el nacimiento, lo que permite no interferir con el contacto piel con piel.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La profilaxis de la enfermedad hemorrágica del recién nacido se realiza con vitamina K:', '1 mg vía oral en dosis única', '1 mg vía intramuscular en dosis única', '5 mg vía intravenosa en dosis única', '0,1 mg/kg vía subcutánea', 'B', 'R-A: se recomienda administrar la vitamina K en dosis única por vía IM (1 mg), método que presenta mejores resultados clínicos para prevenir el síndrome de hemorragia por déficit de vitamina K. El Anexo 8 precisa 0,5-1 mg IM dentro de la primera hora del nacimiento.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto a la relación entre la profilaxis con vitamina K IM y el cáncer infantil, la evidencia señala que:', 'Existe una relación directa comprobada', 'No existe una relación directa', 'Solo se relaciona con leucemia linfoblástica', 'La evidencia es inexistente', 'B', 'E-2a: no existe una relación directa entre el cáncer infantil y la profilaxis con vitamina K IM.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El dato más certero para estimar la edad posconcepcional de un recién nacido en una madre con ciclos regulares es:', 'La ecografía del tercer trimestre', 'La fecha del último período menstrual (FUM)', 'El método de Capurro', 'El peso al nacer', 'B', 'E-4: la fecha del último período menstrual en una madre con ciclos regulares es el dato más certero para estimar la edad posconcepcional; en caso de fertilización asistida, la fecha en que se realizó el procedimiento.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('El método recomendado para la estimación posnatal de la edad gestacional al nacer es:', 'Capurro', 'Dubowitz clásico', 'Ballard modificado (New Ballard)', 'Usher', 'C', 'R-B: se recomienda en el RN el uso del método de Ballard modificado (New Ballard) para la estimación posnatal de la edad gestacional al nacer. Del método de Capurro no se ha encontrado evaluación sistemática de su validez o confiabilidad.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Se recomienda reevaluar la estimación de la edad gestacional cuando no coincide con la EG obstétrica, a las:', '6 y 12 horas de vida', '12 y 24 horas de vida', '24 y 72 horas de vida', '48 y 96 horas de vida', 'C', 'R-D: se recomienda reevaluar la estimación de la edad gestacional a las 24 y 72 horas de vida cuando no resulta coincidente con la EG obstétrica, y en los RN deprimidos al nacer.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Según el normograma de Dawson, la saturación preductal esperable en un recién nacido a los 5 minutos de vida es de:', '60% a 65%', '70% a 75%', '80% a 85%', '90% a 95%', 'C', 'Tabla 1: SpO2 preductal esperable: 1 minuto 60-65%; 2 minutos 65-70%; 3 minutos 70-75%; 4 minutos 75-80%; 5 minutos 80-85%; 10 minutos 85-95%.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En un recién nacido a término que requiere presión positiva en la vía aérea, la reanimación debe iniciarse con:', 'Oxígeno al 100%', 'Aire ambiente (21% FiO2)', 'Mezcla al 60% de oxígeno', 'Oxígeno al 40% con CPAP', 'B', 'R-B: se recomienda en el RN a término que necesite presión positiva en la vía aérea iniciar la reanimación con aire ambiente (21% FiO2). No se recomienda oxígeno de rutina en RN a término sin dificultad para respirar.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('En todo RN que requiere soporte con presión positiva en sala de partos, la oximetría de pulso debe medirse en:', 'La extremidad inferior izquierda', 'La extremidad superior derecha (preductal)', 'La extremidad superior izquierda', 'Indistintamente en cualquier extremidad', 'B', 'R-B: se recomienda medir la oximetría de pulso en la extremidad superior derecha (preductal) y regular la FiO2 con mezclador de aire y oxígeno. El sensor se coloca en la región hipotenar o muñeca de la mano derecha.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto al color de la piel como parámetro en la reanimación neonatal inicial:', 'Es un indicador confiable de la saturación de oxihemoglobina', 'No es un parámetro válido para tomar decisiones', 'Debe utilizarse junto con el APGAR al minuto', 'Es válido solo en el RN pretérmino', 'B', 'R-B y E-1b: la evaluación clínica del color de la piel es un indicador muy pobre de la saturación de oxihemoglobina; el color no es un parámetro válido para tomar decisiones en la reanimación inicial. Tampoco se recomienda esperar la valoración del APGAR para decidir la reanimación.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Según las recomendaciones de identificación del recién nacido, la manilla debe colocarse en:', 'El tobillo derecho', 'La muñeca izquierda', 'La muñeca derecha', 'El tobillo izquierdo', 'B', 'R-P: se recomienda identificar al RN con manilla de plástico o esparadrapo que llevará en su muñeca izquierda, con tinta indeleble, sin tachaduras ni enmendaduras.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Cuál de los siguientes datos NO se exige en el brazalete de identificación del recién nacido?', 'Nombres y apellidos completos de la madre', 'Número de historia clínica', 'Peso al nacer', 'Fecha y hora del nacimiento', 'C', 'R-P: los datos mínimos son nombres y apellidos completos de la madre, gemelo No. en gestaciones múltiples, número de historia clínica, género con palabra completa, sala y número de cama de la madre, y fecha y hora del nacimiento.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La identificación del recién nacido es responsabilidad de:', 'El personal administrativo de admisiones', 'Quien lo recibe y atiende', 'El pediatra de turno exclusivamente', 'La madre y el familiar acompañante', 'B', 'R-P: la identificación del RN es responsabilidad de quien lo recibe y atiende; la manilla debe colocarse y verificarse en presencia de la madre o familiar.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('La Academia Americana de Pediatría define como alta hospitalaria temprana (AHT) aquella que se produce antes de las:', '24 horas después de un parto eutócico', '48 horas después de un parto eutócico', '72 horas después de un parto eutócico', '12 horas después de un parto eutócico', 'B', 'R-D: la AAP define como AHT aquella que se produce antes de las 48 horas después de un parto eutócico.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Respecto a la política de alta hospitalaria posnatal temprana como práctica de rutina, la GPC señala que:', 'Existe evidencia sólida que la respalda', 'La evidencia actual es insuficiente para respaldarla', 'Está contraindicada en todos los casos', 'Debe aplicarse obligatoriamente en el primer nivel', 'B', 'R-C: la evidencia actual es insuficiente para respaldar la política de alta hospitalaria posnatal temprana como práctica de rutina.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('¿Cuál de los siguientes NO es un criterio materno para permitir el alta hospitalaria temprana?', 'Capacidad de deambulación', 'Alimentación oral tolerada', 'Hemoglobina mayor a 12 g/dL', 'Adecuada involución del útero y de la episiotomía si la hubiere', 'C', 'R-P: los criterios maternos son parto vaginal, capacidad de deambulación, alimentación oral tolerada, ausencia de fiebre o enfermedad, no tener enfermedades asociadas al embarazo o agravadas por este, adecuada involución uterina y de la episiotomía, y vivir en un centro urbano con fácil acceso a servicios de salud.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Entre los criterios del recién nacido para el alta hospitalaria temprana se incluye:', 'Haber recibido el baño completo de inmersión', 'Micción y emisión de meconio', 'Peso mayor a 3.000 gramos', 'Haber completado 24 horas de fototerapia', 'B', 'R-P: los criterios del RN incluyen normalidad de signos vitales, exploración neonatal sistemática negativa, ausencia de enfermedad que requiera hospitalización, micción y emisión de meconio, lactancia materna adecuada, despistaje infeccioso negativo si hubiese riesgo, extracción de muestra para hipotiroidismo congénito y conocimiento del HBsAg materno y grupo sanguíneo ABO, Rh y Coombs directo del RN.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP'),
  ('Entre los efectos beneficiosos referidos del alta hospitalaria temprana NO se encuentra:', 'Aumento de la incidencia y duración de la lactancia materna', 'Facilitación del vínculo temprano madre-hijo', 'Disminución de la tasa de reingresos neonatales', 'Mayor implicación del padre en los cuidados del RN', 'C', 'E-2b: los efectos beneficiosos referidos son aumento de la incidencia y duración de la lactancia materna, establecimiento temprano del vínculo madre-hijo, mayor implicación del padre y otros familiares, influencia positiva sobre el entorno familiar, percepción materna de autoconfianza y menor depresión. La reducción de reingresos no se menciona como beneficio.', 'Enfermería - Cuidados de la Mujer, Recién Nacido, Niño y Adolescente', 'PREGUNTAS EHEP')
on conflict do nothing;

notify pgrst, 'reload schema';
